import bpy, os, json
from mathutils import Vector
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
current=os.path.normcase(os.path.normpath(bpy.data.filepath))
if current!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')

def bbox_world(o):
    pts=[o.matrix_world @ Vector(c) for c in o.bound_box]
    return {
        'min':[round(min(p[i] for p in pts),3) for i in range(3)],
        'max':[round(max(p[i] for p in pts),3) for i in range(3)]
    }

def objinfo(o):
    d={
        'name':o.name,
        'type':o.type,
        'loc':[round(float(v),3) for v in o.matrix_world.translation],
        'rot_deg':[round(float(v*57.295779513),3) for v in o.rotation_euler],
        'dims':[round(float(v),3) for v in o.dimensions],
        'collections':[c.name for c in o.users_collection],
        'parent':o.parent.name if o.parent else None,
        'hidden_viewport':bool(o.hide_viewport or o.hide_get()),
        'hidden_render':bool(o.hide_render)
    }
    if o.type in {'MESH','CURVE','FONT','SURFACE','META'}:
        try: d['bbox']=bbox_world(o)
        except Exception: pass
    if o.type=='MESH': d['verts']=len(o.data.vertices)
    return d

keywords=('elevador','lacerda','torre','terreno','estacao','estação','cidade baixa','cidade alta','hall','rua','road','predio','prédio','building','edificio','edifício','praça','praca')
relevant=[]
for o in bpy.data.objects:
    n=o.name.lower()
    if any(k in n for k in keywords): relevant.append(objinfo(o))

parents={}
for c in bpy.data.collections:
    ps=[]
    for p in bpy.data.collections:
        if c.name in [x.name for x in p.children]: ps.append(p.name)
    parents[c.name]=ps

collections=[]
for c in bpy.data.collections:
    n=c.name.lower()
    if any(k in n for k in keywords) or c.name.startswith(('00 ','01 ','02 ','03 ','04 ','A ','B ','C ','D ','WORLD')):
        collections.append({'name':c.name,'parents':parents.get(c.name,[]),'objects':len(c.objects),'children':[x.name for x in c.children]})

terrains=[o for o in bpy.data.objects if o.type=='MESH' and ('terreno' in o.name.lower() or 'terrain' in o.name.lower())]
towers=[o for o in bpy.data.objects if o.type=='MESH' and ('torre' in o.name.lower() or 'elevador' in o.name.lower())]
master=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout')
anchor=next((o for o in bpy.data.objects if o.type=='MESH' and 'torre documental' in o.name.lower()),None)
report={
 'filepath':bpy.data.filepath,
 'scene':bpy.context.scene.name,
 'unit_system':bpy.context.scene.unit_settings.system,
 'scale_length':bpy.context.scene.unit_settings.scale_length,
 'object_count':len(bpy.data.objects),
 'collection_count':len(bpy.data.collections),
 'master_terrain':objinfo(master) if master else None,
 'anchor_tower':objinfo(anchor) if anchor else None,
 'terrain_candidates':[objinfo(o) for o in terrains],
 'tower_candidates':[objinfo(o) for o in towers[:30]],
 'collections':collections,
 'relevant_objects':relevant
}
print('SCENE_STRUCTURE_AUDIT_BEGIN')
print(json.dumps(report,ensure_ascii=False,separators=(',',':')))
print('SCENE_STRUCTURE_AUDIT_END')
